'use server';

/**
 * @fileOverview A tool outline generator AI agent.
 *
 * - generateToolOutline - A function that handles the tool outline generation process.
 * - GenerateToolOutlineInput - The input type for the generateToolOutline function.
 * - GenerateToolOutlineOutput - The return type for the generateToolOutline function.
 */

import {ai} from '@/ai/genkit';
import {z} from 'genkit';

const GenerateToolOutlineInputSchema = z.object({
  topic: z.string().describe('The topic for which to generate a tool outline.'),
});
export type GenerateToolOutlineInput = z.infer<typeof GenerateToolOutlineInputSchema>;

const GenerateToolOutlineOutputSchema = z.object({
  outline: z.string().describe('The generated tool outline in JSON format.'),
});
export type GenerateToolOutlineOutput = z.infer<typeof GenerateToolOutlineOutputSchema>;

export async function generateToolOutline(input: GenerateToolOutlineInput): Promise<GenerateToolOutlineOutput> {
  return generateToolOutlineFlow(input);
}

const prompt = ai.definePrompt({
  name: 'generateToolOutlinePrompt',
  input: {schema: GenerateToolOutlineInputSchema},
  output: {schema: GenerateToolOutlineOutputSchema},
  prompt: `You are an AI assistant that suggests tool outlines based on a given topic.

  Topic: {{{topic}}}

  Please generate a detailed tool outline for the given topic. The outline should be a JSON object with the following structure:
  {
    "id": "a-unique-id-from-the-topic-in-kebab-case",
    "name": "A Tool Name based on the topic",
    "icon": "An appropriate icon name from lucide-react, e.g., 'PenSquare'",
    "layout": [
      {
        "id": "tab-1",
        "name": "Main",
        "panels": [
          {
            "id": "panel-1",
            "title": "Primary Editor",
            "type": "editor",
            "content": "Initial content for the editor...",
            "purpose": "Purpose of this panel for AI suggestions"
          }
        ]
      }
    ]
  }
  `,
});

const generateToolOutlineFlow = ai.defineFlow(
  {
    name: 'generateToolOutlineFlow',
    inputSchema: GenerateToolOutlineInputSchema,
    outputSchema: GenerateToolOutlineOutputSchema,
  },
  async input => {
    const {output} = await prompt(input);
    return output!;
  }
);
